//! Fixture and behavior tests for the treeView renderer.
//!
//! The fixtures in `tests/render/` are generated by
//! `research/mermaid-port/harness/generate-treeview-render-fixtures.mjs`: upstream mermaid
//! rendered under jsdom with the shared monospace measure, read back from the SVG geometry.

use serde_json::Value;

use super::*;
use crate::scene::{Group, Item, PathCommand};

const TOLERANCE: f64 = 0.01;

fn fixtures() -> Vec<(String, Value)> {
    let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("src/diagrams/tree_view/tests/render");
    let mut fixtures: Vec<(String, Value)> = std::fs::read_dir(&dir)
        .unwrap_or_else(|error| panic!("read {}: {error}", dir.display()))
        .map(|entry| entry.expect("dir entry").path())
        .filter(|path| path.extension().and_then(|extension| extension.to_str()) == Some("json"))
        .map(|path| {
            let text = std::fs::read_to_string(&path).expect("read fixture");
            let value: Value = serde_json::from_str(&text).expect("parse fixture");
            (
                path.file_name()
                    .and_then(|name| name.to_str())
                    .unwrap_or_default()
                    .to_string(),
                value,
            )
        })
        .collect();
    fixtures.sort_by(|a, b| a.0.cmp(&b.0));
    fixtures
}

fn close(actual: f64, expected: f64, what: &str, file: &str) {
    assert!(
        (actual - expected).abs() <= TOLERANCE,
        "{file}: {what}: actual {actual} vs expected {expected}"
    );
}

fn number(value: &Value, key: &str, file: &str) -> f64 {
    value
        .get(key)
        .and_then(Value::as_f64)
        .unwrap_or_else(|| panic!("{file}: missing number {key} in {value}"))
}

fn text_of(run: &TextRun) -> String {
    run.lines
        .iter()
        .map(|line| line.text())
        .collect::<Vec<_>>()
        .join("\n")
}

fn color_of(color: &Option<Color>) -> Option<&str> {
    color.as_ref().map(|color| color.0.as_str())
}

fn texts(group: &Group) -> Vec<&TextRun> {
    group
        .items
        .iter()
        .filter_map(|item| match item {
            Item::Text(run) => Some(run),
            _ => None,
        })
        .collect()
}

fn highlight(group: &Group) -> Option<&RectShape> {
    group.items.iter().find_map(|item| match item {
        Item::Rect(rect) => Some(rect),
        _ => None,
    })
}

fn icon(group: &Group) -> Option<&Group> {
    group.items.iter().find_map(|item| match item {
        Item::Group(icon) if icon.class.as_deref() == Some(ICON_GROUP_CLASS) => Some(icon),
        _ => None,
    })
}

fn assert_label(run: &TextRun, expected: &Value, file: &str) {
    let text = expected["text"].as_str().expect("label text");
    assert_eq!(text_of(run), text, "{file}: label text");
    close(run.position.x, number(expected, "x", file), "label x", file);
    close(run.position.y, number(expected, "y", file), "label y", file);
    close(
        run.size.width,
        number(&expected["bbox"], "width", file),
        "label width",
        file,
    );
    close(
        run.size.height,
        number(&expected["bbox"], "height", file),
        "label height",
        file,
    );
    assert_eq!(run.baseline, TextBaseline::Middle, "{file}: label baseline");
    assert_eq!(
        run.anchor,
        crate::scene::TextAnchor::Start,
        "{file}: label anchor"
    );
    assert_eq!(color_of(&run.fill), Some(LABEL_COLOR), "{file}: label fill");
    assert_eq!(run.font.family, "monospace", "{file}: label family");
    assert_eq!(run.font.size, LABEL_FONT_SIZE, "{file}: label size");
    let bold = expected["bold"].as_bool().unwrap_or(false);
    assert_eq!(run.font.is_bold(), bold, "{file}: label weight");
}

fn assert_description(run: &TextRun, expected: &Value, file: &str) {
    let text = expected["text"].as_str().expect("description text");
    assert_eq!(text_of(run), text, "{file}: description text");
    close(
        run.position.x,
        number(expected, "x", file),
        "description x",
        file,
    );
    close(
        run.position.y,
        number(expected, "y", file),
        "description y",
        file,
    );
    close(
        run.size.width,
        number(&expected["bbox"], "width", file),
        "description width",
        file,
    );
    assert_eq!(
        color_of(&run.fill),
        Some(DESCRIPTION_COLOR),
        "{file}: description fill"
    );
    assert!(run.font.italic, "{file}: description italic");
}

fn assert_highlight(rect: &RectShape, expected: &Value, file: &str) {
    close(
        rect.rect.x,
        number(expected, "x", file),
        "highlight x",
        file,
    );
    close(
        rect.rect.y,
        number(expected, "y", file),
        "highlight y",
        file,
    );
    close(
        rect.rect.width,
        number(expected, "width", file),
        "highlight width",
        file,
    );
    close(
        rect.rect.height,
        number(expected, "height", file),
        "highlight height",
        file,
    );
    close(rect.rx, number(expected, "rx", file), "highlight rx", file);
    assert_eq!(
        color_of(&rect.style.fill),
        Some(HIGHLIGHT_BG),
        "{file}: highlight fill"
    );
    assert_eq!(
        color_of(&rect.style.stroke),
        Some(HIGHLIGHT_STROKE),
        "{file}: highlight stroke"
    );
    close(
        rect.style.stroke_width,
        number(expected, "strokeWidth", file),
        "highlight stroke width",
        file,
    );
}

fn assert_commands(actual: &[PathCommand], expected: &Value, file: &str, what: &str) {
    let expected = expected.as_array().expect("command list");
    assert_eq!(actual.len(), expected.len(), "{file}: {what} command count");
    for (index, (command, expected)) in actual.iter().zip(expected).enumerate() {
        let what = format!("{what} command {index}");
        let op = expected["op"].as_str().expect("command op");
        match command {
            PathCommand::MoveTo { x, y } => {
                assert_eq!(op, "moveTo", "{file}: {what}");
                close(*x, number(expected, "x", file), "x", file);
                close(*y, number(expected, "y", file), "y", file);
            }
            PathCommand::LineTo { x, y } => {
                assert_eq!(op, "lineTo", "{file}: {what}");
                close(*x, number(expected, "x", file), "x", file);
                close(*y, number(expected, "y", file), "y", file);
            }
            PathCommand::CubicTo {
                c1x,
                c1y,
                c2x,
                c2y,
                x,
                y,
            } => {
                assert_eq!(op, "cubicTo", "{file}: {what}");
                close(*c1x, number(expected, "c1x", file), "c1x", file);
                close(*c1y, number(expected, "c1y", file), "c1y", file);
                close(*c2x, number(expected, "c2x", file), "c2x", file);
                close(*c2y, number(expected, "c2y", file), "c2y", file);
                close(*x, number(expected, "x", file), "x", file);
                close(*y, number(expected, "y", file), "y", file);
            }
            PathCommand::QuadTo { cx, cy, x, y } => {
                assert_eq!(op, "quadTo", "{file}: {what}");
                close(*cx, number(expected, "cx", file), "cx", file);
                close(*cy, number(expected, "cy", file), "cy", file);
                close(*x, number(expected, "x", file), "x", file);
                close(*y, number(expected, "y", file), "y", file);
            }
            PathCommand::ArcTo {
                rx,
                ry,
                rotation,
                large_arc,
                sweep,
                x,
                y,
            } => {
                assert_eq!(op, "arcTo", "{file}: {what}");
                close(*rx, number(expected, "rx", file), "rx", file);
                close(*ry, number(expected, "ry", file), "ry", file);
                close(
                    *rotation,
                    number(expected, "rotation", file),
                    "rotation",
                    file,
                );
                assert_eq!(
                    *large_arc,
                    expected["large_arc"].as_bool().unwrap_or(false),
                    "{file}: {what} large arc"
                );
                assert_eq!(
                    *sweep,
                    expected["sweep"].as_bool().unwrap_or(false),
                    "{file}: {what} sweep"
                );
                close(*x, number(expected, "x", file), "x", file);
                close(*y, number(expected, "y", file), "y", file);
            }
            PathCommand::Close => assert_eq!(op, "close", "{file}: {what}"),
        }
    }
}

fn assert_icon(group: &Group, expected: &Value, file: &str) {
    let view_box = &expected["viewBox"];
    let width = number(view_box, "width", file);
    let height = number(view_box, "height", file);
    let transform = group.transform;
    close(transform.a, ICON_SIZE / width, "icon transform a", file);
    close(transform.d, ICON_SIZE / height, "icon transform d", file);
    close(transform.b, 0.0, "icon transform b", file);
    close(transform.c, 0.0, "icon transform c", file);
    let origin = &expected["origin"];
    close(
        transform.e,
        number(origin, "x", file),
        "icon origin x",
        file,
    );
    close(
        transform.f,
        number(origin, "y", file),
        "icon origin y",
        file,
    );

    let paths: Vec<&PathShape> = group
        .items
        .iter()
        .filter_map(|item| match item {
            Item::Path(path) => Some(path),
            _ => None,
        })
        .collect();
    let expected_paths = expected["paths"].as_array().expect("icon paths");
    assert_eq!(paths.len(), expected_paths.len(), "{file}: icon path count");
    for (path, expected_path) in paths.iter().zip(expected_paths) {
        assert_commands(
            &path.path.commands,
            &expected_path["commands"],
            file,
            "icon",
        );
        assert_eq!(
            color_of(&path.style.fill),
            expected_path["fill"].as_str(),
            "{file}: icon fill"
        );
        let even_odd = expected_path["fillRule"].as_str() == Some("evenodd");
        assert_eq!(
            path.fill_rule == FillRule::EvenOdd,
            even_odd,
            "{file}: icon fill rule"
        );
    }

    let rects: Vec<&RectShape> = group
        .items
        .iter()
        .filter_map(|item| match item {
            Item::Rect(rect) => Some(rect),
            _ => None,
        })
        .collect();
    let expected_rects = expected["rects"].as_array().expect("icon rects");
    assert_eq!(rects.len(), expected_rects.len(), "{file}: icon rect count");
    for (rect, expected_rect) in rects.iter().zip(expected_rects) {
        close(
            rect.rect.x,
            number(expected_rect, "x", file),
            "icon rect x",
            file,
        );
        close(
            rect.rect.y,
            number(expected_rect, "y", file),
            "icon rect y",
            file,
        );
        close(
            rect.rect.width,
            number(expected_rect, "width", file),
            "icon rect width",
            file,
        );
        close(
            rect.rect.height,
            number(expected_rect, "height", file),
            "icon rect height",
            file,
        );
        assert_eq!(
            color_of(&rect.style.fill),
            expected_rect["fill"].as_str(),
            "{file}: icon rect fill"
        );
    }

    let runs: Vec<&TextRun> = group
        .items
        .iter()
        .filter_map(|item| match item {
            Item::Text(run) => Some(run),
            _ => None,
        })
        .collect();
    let expected_texts = expected["texts"].as_array().expect("icon texts");
    assert_eq!(runs.len(), expected_texts.len(), "{file}: icon text count");
    for (run, expected_text) in runs.iter().zip(expected_texts) {
        assert_eq!(
            text_of(run),
            expected_text["text"].as_str().unwrap_or_default(),
            "{file}: icon text"
        );
        let translate = &expected_text["transform"];
        close(
            run.position.x,
            number(translate, "x", file),
            "icon text x",
            file,
        );
        close(
            run.position.y,
            number(translate, "y", file),
            "icon text y",
            file,
        );
        assert_eq!(
            color_of(&run.fill),
            expected_text["fill"].as_str(),
            "{file}: icon text fill"
        );
    }
}

fn assert_row(group: &Group, expected: &Value, file: &str) {
    let runs = texts(group);
    let label = runs
        .first()
        .unwrap_or_else(|| panic!("{file}: row has no label"));
    assert_label(label, &expected["label"], file);

    match (runs.get(1), expected["description"].is_null()) {
        (Some(description), false) => {
            assert_description(description, &expected["description"], file)
        }
        (None, true) => {}
        (Some(_), true) => panic!("{file}: unexpected description"),
        (None, false) => panic!("{file}: missing description"),
    }

    match (highlight(group), expected["highlight"].is_null()) {
        (Some(rect), false) => assert_highlight(rect, &expected["highlight"], file),
        (None, true) => {}
        (Some(_), true) => panic!("{file}: unexpected highlight"),
        (None, false) => panic!("{file}: missing highlight"),
    }

    match (icon(group), expected["icon"].is_null()) {
        (Some(icon), false) => assert_icon(icon, &expected["icon"], file),
        (None, true) => {}
        (Some(_), true) => panic!("{file}: unexpected icon"),
        (None, false) => panic!("{file}: missing icon"),
    }
}

fn assert_line(shape: &PathShape, expected: &Value, file: &str) {
    assert_eq!(shape.path.commands.len(), 2, "{file}: line command count");
    let PathCommand::MoveTo { x: x1, y: y1 } = shape.path.commands[0] else {
        panic!("{file}: line does not start with a move");
    };
    let PathCommand::LineTo { x: x2, y: y2 } = shape.path.commands[1] else {
        panic!("{file}: line does not end with a line");
    };
    close(x1, number(expected, "x1", file), "line x1", file);
    close(y1, number(expected, "y1", file), "line y1", file);
    close(x2, number(expected, "x2", file), "line x2", file);
    close(y2, number(expected, "y2", file), "line y2", file);
    close(
        shape.style.stroke_width,
        number(expected, "strokeWidth", file),
        "line stroke width",
        file,
    );
    assert_eq!(
        color_of(&shape.style.stroke),
        expected["stroke"].as_str(),
        "{file}: line stroke"
    );
}

fn assert_scene(scene: &Scene, expected: &Value, file: &str) {
    let view_box = &expected["viewBox"];
    close(
        scene.view_box.x,
        number(view_box, "x", file),
        "viewBox x",
        file,
    );
    close(
        scene.view_box.y,
        number(view_box, "y", file),
        "viewBox y",
        file,
    );
    close(
        scene.view_box.width,
        number(view_box, "width", file),
        "viewBox width",
        file,
    );
    close(
        scene.view_box.height,
        number(view_box, "height", file),
        "viewBox height",
        file,
    );

    let Item::Group(tree) = scene
        .items
        .first()
        .unwrap_or_else(|| panic!("{file}: no tree group"))
    else {
        panic!("{file}: the first item is not a group");
    };
    assert_eq!(
        tree.class.as_deref(),
        Some(TREE_GROUP_CLASS),
        "{file}: tree group class"
    );

    let ordered = expected["ordered"].as_array().expect("ordered items");
    assert_eq!(
        tree.items.len(),
        ordered.len(),
        "{file}: item count: {:?}",
        tree.items
    );
    for (index, (item, expected)) in tree.items.iter().zip(ordered).enumerate() {
        let kind = expected["kind"].as_str().expect("item kind");
        match (kind, item) {
            ("row", Item::Group(group)) => assert_row(group, expected, file),
            ("line", Item::Path(shape)) => assert_line(shape, expected, file),
            _ => panic!("{file}: item {index} is a {kind} mismatch"),
        }
    }
}

#[test]
fn renders_recorded_tree_view_fixtures() {
    let fixtures = fixtures();
    assert!(
        fixtures.len() >= 8,
        "expected at least 8 treeView fixtures, found {}",
        fixtures.len()
    );
    for (file, fixture) in fixtures {
        let source = fixture["source"].as_str().expect("fixture source");
        let scene = crate::render_diagram(source, &Config::default())
            .unwrap_or_else(|error| panic!("{file}: render failed: {error}"));
        assert_scene(&scene, &fixture["expected"], &file);
    }
}

#[test]
fn draws_styles_lines_and_columns_like_styles_ts() {
    let source = "treeView-beta\n  src/ :::highlight icon(folder) ## Sources\n    main.rs\n";
    let scene = render(source, &Config::default()).expect("render");
    let Item::Group(tree) = &scene.items[0] else {
        panic!("no tree group");
    };

    let Item::Group(root) = &tree.items[0] else {
        panic!("no root row");
    };
    let root_texts = texts(root);
    let label = root_texts.first().expect("root label");
    assert!(label.font.is_bold(), "directories are bold");
    assert_eq!(color_of(&label.fill), Some(LABEL_COLOR));

    let Item::Group(src) = &tree.items[2] else {
        panic!("no src row");
    };
    let rect = highlight(src).expect("src highlight");
    assert_eq!(color_of(&rect.style.fill), Some(HIGHLIGHT_BG));
    assert_eq!(rect.rx, HIGHLIGHT_RADIUS);
    let icon = icon(src).expect("src icon");
    assert_eq!(icon.class.as_deref(), Some(ICON_GROUP_CLASS));

    let Item::Path(line) = &tree.items[3] else {
        panic!("no branch line");
    };
    assert_eq!(color_of(&line.style.stroke), Some(LINE_COLOR));
    assert_eq!(line.style.stroke_width, 1.0);
}

#[test]
fn renders_the_configured_row_geometry() {
    let mut config = Config::default();
    config.tree_view.row_indent = 4.0;
    config.tree_view.padding_x = 2.0;
    config.tree_view.padding_y = 8.0;
    config.tree_view.line_thickness = 2.0;
    let scene = render("treeView-beta\n  a/\n    b/\n      c.txt\n", &config).expect("render");
    // The synthetic root plus three nodes: each row is 16 * 1.15 + 2 * 8 high, indents step by
    // 4 + 2, and the viewBox starts at -1.
    close(scene.view_box.x, -1.0, "viewBox x", "inline");
    close(
        scene.view_box.height,
        4.0 * 34.4,
        "viewBox height",
        "inline",
    );
    let Item::Group(tree) = &scene.items[0] else {
        panic!("no tree group");
    };
    let Item::Path(first) = &tree.items[1] else {
        panic!("no first branch");
    };
    let PathCommand::MoveTo { x, .. } = first.path.commands[0] else {
        panic!("branch does not move");
    };
    close(x, -4.0, "root branch x1", "inline");
}

#[test]
fn resolves_icons_like_get_node_icon() {
    let mut config = TreeViewConfig::default();
    let file = Node {
        id: 1,
        level: 0,
        name: "main.rs".to_string(),
        node_type: NodeType::File,
        icon: None,
        css_class: None,
        description: None,
        children: Vec::new(),
    };
    assert_eq!(get_node_icon(&file, &config), None);
    config.show_icons = true;
    assert_eq!(
        get_node_icon(&file, &config),
        Some("mermaid-treeview:file".to_string())
    );
    config
        .extension_icons
        .insert(".rs".to_string(), Value::String("custom:rust".to_string()));
    assert_eq!(
        get_node_icon(&file, &config),
        Some("custom:rust".to_string())
    );
    config
        .filename_icons
        .insert("main.rs".to_string(), Value::String("none".to_string()));
    assert_eq!(get_node_icon(&file, &config), None);

    let mut annotated = file.clone();
    annotated.icon = Some("folder".to_string());
    assert_eq!(
        get_node_icon(&annotated, &config),
        Some("mermaid-treeview:folder".to_string())
    );
    annotated.icon = Some("none".to_string());
    assert_eq!(get_node_icon(&annotated, &config), None);

    let directory = Node {
        node_type: NodeType::Directory,
        name: "src".to_string(),
        icon: None,
        ..annotated
    };
    assert_eq!(
        get_node_icon(&directory, &config),
        Some("mermaid-treeview:folder".to_string())
    );
}

#[test]
fn render_diagram_dispatches_tree_view() {
    let scene = crate::render_diagram(
        "treeView-beta\n  src/\n    main.rs\n  README.md\n",
        &Config::default(),
    )
    .expect("render_diagram");
    assert!(scene.view_box.width > 0.0);
    assert!(scene.view_box.height > 0.0);
    assert_eq!(
        scene.items.first().and_then(|item| match item {
            Item::Group(group) => group.class.as_deref(),
            _ => None,
        }),
        Some(TREE_GROUP_CLASS)
    );
}

